using Npgsql;
using System.Text.Json.Nodes;
using System.Security.Cryptography;
using System.Text;
using TWM.API.Models;
using static TWM.API.Services.StateService;
namespace TWM.API.Services;
public sealed class AccountService(DatabaseService database){
 public static string Rut(string value){var clean=value.Replace(".","").Replace("-","").Trim().ToUpperInvariant();if(clean.Length is <8 or >9||!clean[..^1].All(char.IsAsciiDigit))throw new ArgumentException("RUT inválido.");int sum=0,m=2;foreach(var digit in clean[..^1].Reverse()){sum+=(digit-'0')*m;m=m==7?2:m+1;}var n=11-sum%11;var dv=n==11?"0":n==10?"K":n.ToString();if(clean[^1].ToString()!=dv)throw new ArgumentException("RUT inválido.");return clean[..^1]+"-"+dv;}
 public async Task<JsonObject?> Profile(string rut,CancellationToken ct){await using var c=await database.Open(ct);var rows=await RelationalStore.Query(c,null,"""
 SELECT jsonb_build_object('rut',coalesce(c.run,e.run),'run',coalesce(c.run,e.run),'nombre',coalesce(c.nombre,e.nombre)||' '||coalesce(c.apellido,e.apellido),'fechaNacimiento',coalesce(c.fechanac,e.fechanac),'role',CASE WHEN e.run IS NOT NULL AND (p.allowed_roles IS NULL OR p.allowed_roles ? 'Emprendedor') THEN 'Vendedor' ELSE 'Comprador' END,'canBuy',c.run IS NOT NULL AND (p.allowed_roles IS NULL OR p.allowed_roles ? 'Cliente'),'canSell',e.run IS NOT NULL AND (p.allowed_roles IS NULL OR p.allowed_roles ? 'Emprendedor'),'canAdmin',coalesce(p.admin,false),'active',coalesce(p.active,true),'authVersion',coalesce(p.auth_version,''),'email',coalesce((SELECT correo FROM public.correo WHERE cliente_id=c.run ORDER BY correo LIMIT 1),(SELECT correo FROM public.correo WHERE emprendedor_id=e.run ORDER BY correo LIMIT 1),''),'telefono',coalesce((SELECT telefono FROM public.telefono WHERE cliente_id=c.run ORDER BY telefono LIMIT 1),(SELECT telefono FROM public.telefono WHERE emprendedor_id=e.run ORDER BY telefono LIMIT 1),''),'direccion',coalesce((SELECT calle||' '||numero FROM public.direccion WHERE cliente_id=c.run OR emprendedor_id=e.run ORDER BY id LIMIT 1),''))::text
 FROM public.cliente c FULL JOIN public.emprendedor e ON c.run=e.run LEFT JOIN shopping_ui.principals p ON p.rut=coalesce(c.run,e.run) WHERE coalesce(c.run,e.run)=@rut
 """,ct,("rut",rut));return rows.FirstOrDefault()?.AsObject();}
 public async Task<JsonObject?> Login(LoginRequest request,CancellationToken ct){var rut=Rut(request.Rut);if(Encoding.UTF8.GetByteCount(request.Password)>72)return null;await using var c=await database.Open(ct);var hashes=await RelationalStore.Query(c,null,"SELECT jsonb_build_object('hash',passwd)::text FROM public.cliente WHERE run=@rut UNION ALL SELECT jsonb_build_object('hash',passwd)::text FROM public.emprendedor WHERE run=@rut",ct,("rut",rut));bool accepted=false,legacy=false;foreach(var row in hashes){var hash=Text(row,"hash");if(hash.StartsWith("$2")){if(BCrypt.Net.BCrypt.Verify(request.Password,hash))accepted=true;}else if(hash.Length==64){var digest=Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(request.Password)));if(CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(hash.ToLowerInvariant()),Encoding.UTF8.GetBytes(digest))){accepted=true;legacy=true;}}}if(!accepted)return null;var profile=await Profile(rut,ct);if(profile?["active"]?.GetValue<bool>()==false)return null;if(legacy)await StorePassword(c,null,rut,request.Password,false,ct);return profile;}
 static async Task StorePassword(NpgsqlConnection c,NpgsqlTransaction? tx,string rut,string password,bool revoke,CancellationToken ct){if(Encoding.UTF8.GetByteCount(password) is <8 or >72)throw new ArgumentException("La contraseña debe tener entre 8 y 72 bytes.");var hash=BCrypt.Net.BCrypt.HashPassword(password,12);await RelationalStore.Exec(c,tx,"UPDATE public.cliente SET passwd=@hash WHERE run=@rut;UPDATE public.emprendedor SET passwd=@hash WHERE run=@rut",ct,("hash",hash),("rut",rut));if(revoke)await RelationalStore.Exec(c,tx,"INSERT INTO shopping_ui.principals(rut,auth_version) VALUES(@rut,@version) ON CONFLICT(rut) DO UPDATE SET auth_version=EXCLUDED.auth_version",ct,("rut",rut),("version",Guid.NewGuid().ToString("N")));}
 public async Task ChangePassword(string rut,PasswordRequest request,CancellationToken ct){if(await Login(new(rut,request.Current),ct)==null)throw new UnauthorizedAccessException();if(request.Current==request.Next)throw new ArgumentException("Usa una contraseña diferente.");await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);await StorePassword(c,tx,rut,request.Next,true,ct);await tx.CommitAsync(ct);}
 public async Task<JsonObject> Register(RegisterRequest request,CancellationToken ct){if(Encoding.UTF8.GetByteCount(request.Password) is <8 or >72)throw new ArgumentException("La contraseña debe tener entre 8 y 72 bytes.");var rut=Rut(request.Rut);if(request.FechaNacimiento.Year<1940||request.FechaNacimiento>DateOnly.FromDateTime(DateTime.Today))throw new ArgumentException("Fecha de nacimiento inválida: desde 1940 hasta hoy.");if(request.Rol is not ("cliente" or "vendedor")||request.Nombre.Trim().Length<3||!System.Net.Mail.MailAddress.TryCreate(request.Email,out _)||!System.Text.RegularExpressions.Regex.IsMatch(request.Telefono,@"^\+?[0-9 ()-]{8,18}$"))throw new ArgumentException("Datos de registro inválidos.");if(await Profile(rut,ct)!=null)throw new ArgumentException("El RUT ya está registrado.");await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);await RelationalStore.Exec(c,tx,"SELECT pg_advisory_xact_lock(7281156)",ct);var names=request.Nombre.Trim().Split(' ',2);var hash=BCrypt.Net.BCrypt.HashPassword(request.Password,12);var tables=request.Rol=="vendedor"?new[]{"cliente","emprendedor"}:new[]{"cliente"};foreach(var table in tables)await RelationalStore.Exec(c,tx,$"INSERT INTO public.{table}(run,nombre,apellido,fechanac,passwd) VALUES(@rut,@name,@surname,@born,@hash)",ct,("rut",rut),("name",names[0]),("surname",names.Length>1?names[1]:""),("born",request.FechaNacimiento),("hash",hash));await RelationalStore.Contacts(c,tx,"cliente_id",rut,request.Email,new JsonArray(request.Telefono),ct);if(request.Address==null||Number(request.Address,"number")<=0||Number(request.Address,"communeId")<=0||Text(request.Address,"street").Trim().Length<3)throw new ArgumentException("Completa calle, número y comuna de la dirección inicial.");var addressId=await RelationalStore.Next(c,tx,"direccion","id",ct);await RelationalStore.Exec(c,tx,"INSERT INTO public.direccion(id,calle,numero,comuna_id,cliente_id) VALUES(@id,@street,@number,@commune,@rut);INSERT INTO public.registrar(cliente_id,direccion_id) VALUES(@rut,@id)",ct,("id",addressId),("street",Text(request.Address,"street")),("number",(int)Number(request.Address,"number")),("commune",(int)Number(request.Address,"communeId")),("rut",rut));await RelationalStore.Exec(c,tx,"UPDATE shopping_ui.state_version SET revision=revision+1 WHERE id=1",ct);await tx.CommitAsync(ct);return (await Profile(rut,ct))!;}
 public async Task UpdateProfile(NpgsqlConnection c,NpgsqlTransaction tx,string rut,JsonObject profile,CancellationToken ct){if(Text(profile,"fullName").Trim().Length<3||!System.Net.Mail.MailAddress.TryCreate(Text(profile,"email"),out _))throw new ArgumentException("Nombre o correo inválidos.");var months=new[]{"Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"};var month=Array.IndexOf(months,Text(profile,"birthMonth"))+1;if(!DateOnly.TryParse($"{Text(profile,"birthYear")}-{month:D2}-{Number(profile,"birthDay"):00}",out var birth)||birth.Year<1940||birth>DateOnly.FromDateTime(DateTime.Today))throw new ArgumentException("Fecha inválida.");var names=Text(profile,"fullName").Trim().Split(' ',2);await RelationalStore.Exec(c,tx,"UPDATE public.cliente SET nombre=@name,apellido=@surname,fechanac=@birth WHERE run=@rut;UPDATE public.emprendedor SET nombre=@name,apellido=@surname,fechanac=@birth WHERE run=@rut",ct,("rut",rut),("name",names[0]),("surname",names.Length>1?names[1]:""),("birth",birth));var isClient=await RelationalStore.Query(c,tx,"SELECT jsonb_build_object('run',run)::text FROM public.cliente WHERE run=@rut",ct,("rut",rut));await RelationalStore.Contacts(c,tx,isClient.Count>0?"cliente_id":"emprendedor_id",rut,Text(profile,"email"),new JsonArray(Rows(profile["phones"]).Select(p=>(JsonNode?)JsonValue.Create(Text(p,"number"))).ToArray()),ct);}
 public async Task ResetPassword(string rut,string password,CancellationToken ct){rut=Rut(rut);if(await Profile(rut,ct)==null)throw new ArgumentException("El RUT no existe en la base cargada.");await using var c=await database.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);await StorePassword(c,tx,rut,password,true,ct);await tx.CommitAsync(ct);}
 public async Task SetAdministrator(string rut,CancellationToken ct){rut=Rut(rut);if(await Profile(rut,ct)==null)throw new ArgumentException("El RUT no existe en public.cliente/emprendedor.");await using var c=await database.Open(ct);await RelationalStore.Exec(c,null,"INSERT INTO shopping_ui.principals(rut,admin) VALUES(@rut,true) ON CONFLICT(rut) DO UPDATE SET admin=true,active=true",ct,("rut",rut));}
}
